"""Read labels generated by verify-barcode-geometry.mts with independent ZXing-C++."""
import hashlib
import json
from importlib.metadata import version
from pathlib import Path
import sys
from PIL import Image
import zxingcpp

labels = Path(sys.argv[1])
records = json.loads((labels / 'manifest.json').read_text(encoding='utf-8'))
assert records
for record in records:
    image_path = labels / (record['barcode'] + '.png')
    assert hashlib.sha256(image_path.read_bytes()).hexdigest() == record['sha256']
    with Image.open(image_path) as image:
        decoded = zxingcpp.read_barcode(image, formats=zxingcpp.BarcodeFormat.Code128)
    assert decoded and decoded.text == record['barcode'], record
report = {'decoder': 'zxing-cpp', 'version': version('zxing-cpp'), 'geometryLabels': len(records), 'decoded': len(records), 'unique': len({r['barcode'] for r in records}), 'records': records}
Path(sys.argv[2]).write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding='utf-8')
print(json.dumps({key: value for key, value in report.items() if key != 'records'}))
